// The social share image (Open Graph and Twitter cards). It is generated by
// `npm run og` into public/og.png; the size is part of the card markup, so it
// lives here next to the path.
import { displayName, site } from './site';

export const socialImage = {
  path: '/og.png',
  width: 1200,
  height: 630,
  alt: `${displayName} (${site.handle}): ${site.tagline ?? 'projects, CV and contact'}`,
} as const;
